  @keyframes tripA{0%{transform:translate(-24vw,0)}18%{transform:translate(6vw,-48px)}36%{transform:translate(30vw,22px)}54%{transform:translate(54vw,-42px)}72%{transform:translate(82vw,28px)}100%{transform:translate(126vw,-16px)}}
  @keyframes tripB{0%{transform:translate(-24vw,42px)}20%{transform:translate(14vw,-22px)}40%{transform:translate(42vw,50px)}62%{transform:translate(74vw,-36px)}100%{transform:translate(126vw,-48px)}}
