  .pase-cuerpo>p{color:var(--tinta2);font-size:clamp(1rem,1.3vw,1.1rem);line-height:1.6;max-width:44ch;margin-bottom:0}

    border-radius:6px;overflow:hidden;margin-bottom:20px}
    text-transform:uppercase;color:var(--esm);margin-bottom:3px}

    font-family:var(--display);font-weight:800;font-size:.76rem;letter-spacing:.11em;text-transform:uppercase;
    padding:15px 25px;border-radius:8px;transition:transform .25s ease,background .25s ease,box-shadow .25s ease;
    box-shadow:0 10px 24px rgba(59,131,117,.26)}

  /* foto a la derecha, como el panel de una tarjeta real */
