  .mes-cuerpo a::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--coral);flex-shrink:0}

  .acceso{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;
    padding:clamp(1.1rem,2.2vw,1.5rem) clamp(1.1rem,2.4vw,1.6rem);border-radius:12px;
    background:linear-gradient(120deg,rgba(220,233,225,.7),rgba(252,253,251,.9));border:1px solid rgba(59,131,117,.3)}
  .acc-info b{display:block;font-family:var(--edit);font-weight:600;font-size:clamp(1.05rem,1.9vw,1.25rem);
    color:var(--tinta);text-transform:none;letter-spacing:0;margin-bottom:4px}
  .acc-info span{display:block;font-family:var(--display);font-weight:700;font-size:.72rem;letter-spacing:.16em;
    text-transform:uppercase;color:var(--esm)}
  .btn-acceso{display:inline-flex;align-items:center;gap:10px;background:var(--esm);color:#fff;
    font-family:var(--display);font-weight:800;font-size:.76rem;letter-spacing:.1em;text-transform:uppercase;
    padding:15px 24px;border-radius:9px;box-shadow:0 10px 22px rgba(59,131,117,.26);
    transition:background .25s ease,transform .25s ease}
  .btn-acceso:hover{background:var(--tinta);transform:translateY(-2px)}
  .btn-acceso .arw{transition:transform .25s ease}
  .btn-acceso:hover .arw{transform:translateX(4px)}

  /* --- listas --- */
  .lista{display:flex;flex-direction:column;gap:8px}
  .item{display:flex;align-items:center;gap:12px;padding:13px 15px;border-radius:11px;background:#fff;
    border:1px solid rgba(59,131,117,.2);transition:border-color .2s ease,transform .2s ease,box-shadow .2s ease}
  .item:hover{border-color:rgba(59,131,117,.5);transform:translateX(3px);box-shadow:0 6px 16px rgba(35,78,72,.06)}
  .item .i-ico{color:var(--esm);line-height:0;flex-shrink:0}
  .item .i-ico svg{width:18px;height:18px}
  .item b{font-family:var(--edit);font-weight:600;font-size:.98rem;color:var(--tinta);text-transform:none;letter-spacing:0;display:block}
  .item small{display:block;color:var(--tinta2);font-size:.78rem;margin-top:2px;font-family:var(--sans)}
  .item .arw{margin-left:auto;color:var(--coral)}

  /* --- ayuda --- */
  .ayuda{position:relative;margin-top:clamp(2rem,3.6vw,2.8rem);display:flex;align-items:center;justify-content:space-between;
    gap:1.2rem;flex-wrap:wrap;padding:clamp(1.4rem,2.6vw,2rem) clamp(1.4rem,2.8vw,2.2rem);border-radius:16px;
    background:var(--marfil);border:1px solid rgba(59,131,117,.26)}
  .ayuda h3{font-family:var(--edit);font-weight:600;text-transform:none;letter-spacing:-.01em;font-size:1.25rem;color:var(--tinta);margin-bottom:5px}
  .ayuda p{color:var(--tinta2);font-size:.93rem}
  .btn-ayuda{display:inline-flex;align-items:center;gap:9px;border:1.5px solid var(--esm);color:var(--esm);
    font-family:var(--display);font-weight:800;font-size:.72rem;letter-spacing:.09em;text-transform:uppercase;
    padding:13px 20px;border-radius:100px;transition:background .25s ease,color .25s ease}
  .btn-ayuda:hover{background:var(--esm);color:#fff}
  .instructivo-wrap{text-align:center;margin-top:clamp(1.6rem,3vw,2.2rem)}
  .btn-instructivo{display:inline-flex;align-items:center;gap:11px;background:#E3CDA9;color:#1B4F45;
    font-family:var(--display);font-weight:800;font-size:.76rem;letter-spacing:.1em;text-transform:uppercase;
    padding:15px 26px;border-radius:100px;border:1px solid rgba(160,128,72,.34);
    box-shadow:0 8px 20px rgba(160,128,72,.2);transition:background .25s ease,transform .25s ease,box-shadow .25s ease}
  .btn-instructivo:hover{background:#D9BE94;transform:translateY(-2px);box-shadow:0 12px 26px rgba(146,113,52,.3)}
  .bi-ico{line-height:0}
  .bi-ico svg{width:18px;height:18px}

  /* --- fondo con la playa + palabras flotando --- */
  .fondo-playa{position:fixed;inset:0;z-index:-3;filter:blur(2.5px) saturate(1.06) brightness(1.05);transform:scale(1.04);background-image:url('/legacy-assets/6cd5020661e4b676.jpg');
    background-size:cover;background-position:center;pointer-events:none}
  .fondo-velo{position:fixed;inset:0;z-index:-2;pointer-events:none;
    background:linear-gradient(180deg,rgba(243,249,246,.88) 0%,rgba(238,247,244,.83) 42%,rgba(243,249,246,.9) 100%)}
  .palabras{position:fixed;inset:0;z-index:-1;overflow:hidden;pointer-events:none}
  .pal{position:absolute;font-family:var(--edit,var(--font-display),Georgia,serif);font-style:italic;font-weight:400;
    color:#fff;text-shadow:0 2px 10px rgba(35,78,72,.18);white-space:nowrap;opacity:0;
    animation-name:flotar;animation-timing-function:ease-in-out;animation-iteration-count:infinite;transform:rotate(var(--r));will-change:transform,opacity}
  @keyframes flotar{
    0%{transform:translate3d(0,0,0) rotate(var(--r)) scale(1);opacity:calc(var(--o) * .55)}
    50%{transform:translate3d(3px,-9px,0) rotate(var(--r)) scale(1.03);opacity:var(--o)}
    100%{transform:translate3d(0,0,0) rotate(var(--r)) scale(1);opacity:calc(var(--o) * .55)}
  }
  @media(max-width:1240px){.palabras{display:none}}
  @media(prefers-reduced-motion:reduce){.pal{animation:none;opacity:calc(var(--o) * .5);transform:none}}

  /* ===== GUIA DE VIAJE ===== */
  .guia-head{text-align:center;max-width:640px;margin:0 auto clamp(2.2rem,4vw,3.2rem)}
  .guia-head .kicker{margin-bottom:14px}
  .guia-head h1{font-family:var(--edit);font-weight:600;text-transform:none;letter-spacing:-.02em;line-height:1.06;
    font-size:clamp(1.9rem,4.4vw,2.9rem);color:var(--tinta);margin-bottom:14px}
  .guia-head h1 em{font-style:italic;font-weight:400;color:var(--esm2)}
  .guia-head p{color:var(--tinta2);font-size:clamp(1rem,1.3vw,1.12rem);line-height:1.6}

  .bloque{background:rgba(252,253,251,.93);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);border:1px solid rgba(59,131,117,.26);border-radius:16px;
    padding:clamp(1.5rem,3vw,2.3rem) clamp(1.4rem,3vw,2.2rem);margin-bottom:clamp(1rem,2vw,1.4rem)}
  .bloque>h2{font-family:var(--edit);font-weight:600;text-transform:none;letter-spacing:-.02em;text-align:center;
    font-size:clamp(1.7rem,3.4vw,2.5rem);line-height:1.1;color:var(--tinta);margin-bottom:10px}
  .bloque>.sub{color:var(--tinta2);font-size:clamp(1.02rem,1.35vw,1.15rem);line-height:1.6;text-align:center;
    margin:0 auto clamp(1.6rem,3vw,2.4rem);max-width:56ch}

  .pasos{list-style:none;display:flex;flex-direction:column;gap:clamp(1.1rem,2.2vw,1.6rem)}
  .paso{display:flex;gap:clamp(14px,2.2vw,20px);align-items:flex-start}
  .paso .n{flex-shrink:0;width:38px;height:38px;border-radius:50%;border:1.5px solid rgba(59,131,117,.45);
    color:var(--esm);font-family:var(--display);font-weight:900;font-size:.92rem;display:flex;align-items:center;justify-content:center}
  .paso b{display:block;font-family:var(--display);font-weight:800;text-transform:none;letter-spacing:-.005em;
    font-size:1.04rem;color:var(--tinta);margin-bottom:5px}
  .paso p{color:var(--tinta2);font-size:.94rem;line-height:1.6;max-width:60ch}

  .fichas{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  @media(max-width:720px){.fichas{grid-template-columns:1fr}}
  .ficha{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid rgba(59,131,117,.22);
    border-radius:12px;padding:16px 18px}
  .ficha .f-ico{color:var(--esm);line-height:0;flex-shrink:0;margin-top:2px}
  .ficha .f-ico svg{width:20px;height:20px}
  .ficha b{display:block;font-family:var(--display);font-weight:800;font-size:.96rem;color:var(--tinta);
    text-transform:none;letter-spacing:0;margin-bottom:4px}
  .ficha span{display:block;color:var(--tinta2);font-size:.87rem;line-height:1.5}

  .faq-guia{display:flex;flex-direction:column;gap:9px}
  .fq{background:#fff;border:1px solid rgba(59,131,117,.22);border-radius:11px;overflow:hidden;transition:border-color .2s ease}
  .fq[open]{border-color:rgba(59,131,117,.5)}
  .fq summary{list-style:none;display:flex;align-items:center;gap:12px;cursor:pointer;padding:14px 16px}
  .fq summary::-webkit-details-marker{display:none}
  .fq summary b{flex:1;font-family:var(--display);font-weight:700;font-size:.95rem;color:var(--tinta);text-transform:none;letter-spacing:0}
  .fq summary .signo{color:var(--esm);font-size:1.1rem;line-height:1;transition:transform .3s ease}
  .fq[open] summary .signo{transform:rotate(45deg)}
  .fq-cuerpo{display:grid;grid-template-rows:0fr;transition:grid-template-rows .3s ease}
  .fq[open] .fq-cuerpo{grid-template-rows:1fr}
  .fq-cuerpo>div{overflow:hidden}
  .fq-cuerpo p{padding:0 16px 15px;color:var(--tinta2);font-size:.9rem;line-height:1.6}

  .volver-espacio{text-align:center;margin-top:clamp(1.8rem,3.4vw,2.6rem)}
  .btn-volver{display:inline-flex;align-items:center;gap:10px;background:var(--esm);color:#fff;
    font-family:var(--display);font-weight:800;font-size:.76rem;letter-spacing:.1em;text-transform:uppercase;
    padding:15px 26px;border-radius:100px;box-shadow:0 10px 22px rgba(59,131,117,.24);transition:background .25s ease,transform .25s ease}
  .btn-volver:hover{background:var(--tinta);transform:translateY(-2px)}

  /* --- aviones en primeros pasos --- */
  .bloque-pasos{position:relative;overflow:hidden;background:linear-gradient(160deg,#EAF4F6,var(--marfil) 65%)}

  /* --- pases de "que vas a encontrar" --- */
  .bloque-pases{position:relative;overflow:hidden;left:50%;transform:translateX(-50%);width:min(1180px,94vw)}
  @media(max-width:1000px){.bloque-pases{left:auto;transform:none;width:auto}}
  .globo{position:absolute;right:-30px;top:-24px;width:clamp(130px,15vw,190px);opacity:.13;pointer-events:none}
  }
  /* ===== PRIMEROS PASOS (itinerario limpio) ===== */
  .bloque-pasos{position:relative;overflow:hidden;background:linear-gradient(170deg,rgba(236,246,246,.86),rgba(253,253,250,.94) 60%)}
  .bloque-pasos>h2,.bloque-pasos>.sub,.bloque-pasos>.itinerario,.bloque-pasos>.it-coord{position:relative;z-index:1}
  .bloque-pasos .it-sello{display:block;position:absolute;right:clamp(12px,3vw,34px);bottom:clamp(12px,2.4vw,26px);
    width:clamp(74px,7.5vw,96px);height:clamp(74px,7.5vw,96px);color:rgba(59,131,117,.13);transform:rotate(-8deg);
    pointer-events:none;z-index:0}
  .bloque-pasos .it-sello svg{width:100%;height:100%;display:block}
  .it-coord{display:block;text-align:right;margin-top:clamp(1.2rem,2.4vw,1.8rem);font-family:var(--display);
    font-weight:700;font-size:.56rem;letter-spacing:.2em;color:rgba(93,124,118,.55)}
  .itinerario{list-style:none;position:relative;display:flex;flex-direction:column;
    gap:clamp(1.7rem,3.4vw,2.6rem);padding-left:2px}
  .itinerario::before{content:"";position:absolute;left:21px;top:26px;bottom:26px;
    border-left:1.5px dotted rgba(59,131,117,.45);z-index:0}
  .it{display:grid;grid-template-columns:44px 1fr;gap:clamp(14px,1.8vw,20px);align-items:start;position:relative;z-index:1}
  .it-num{width:44px;height:44px;border-radius:50%;background:#fff;border:1.5px solid rgba(59,131,117,.45);
    color:var(--esm);font-family:var(--display);font-weight:900;font-size:.9rem;letter-spacing:.02em;
    display:flex;align-items:center;justify-content:center}
  .it-cont{padding-top:5px}
  .it-cont b{display:block;font-family:var(--edit);font-weight:600;text-transform:none;letter-spacing:-.015em;
    font-size:clamp(1.14rem,2.1vw,1.42rem);line-height:1.18;color:var(--tinta);margin-bottom:8px}
  .it-cont p{color:var(--tinta2);font-size:clamp(.94rem,1.2vw,1.02rem);line-height:1.7;max-width:64ch;font-weight:400}

  /* ===== PANEL DE DESTINOS ===== */
  .bloque-pases{position:relative;overflow:hidden;left:50%;transform:translateX(-50%);width:min(1100px,94vw)}
  @media(max-width:1000px){.bloque-pases{left:auto;transform:none;width:auto}}
  .bloque-pases .globo{position:absolute;right:-24px;top:-20px;width:clamp(120px,13vw,168px);opacity:.09;pointer-events:none;z-index:0}
  .bloque-pases>h2,.bloque-pases>.sub{position:relative;z-index:1}

  /* ===== TARJETAS DE EMBARQUE ===== */
  .pasajes{display:flex;flex-direction:column;gap:clamp(1rem,2vw,1.5rem);position:relative;z-index:1}
  .bp{position:relative;display:grid;grid-template-columns:1fr 96px;border-radius:14px;
    border:1px solid rgba(59,131,117,.28);background:#FDFCF8;overflow:visible;
    box-shadow:0 3px 14px rgba(35,78,72,.05);transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease}
  .bp:hover{transform:translateY(-3px);box-shadow:0 12px 26px rgba(35,78,72,.09);border-color:rgba(59,131,117,.5)}
  @media(max-width:680px){.bp{grid-template-columns:1fr}}
  .bp1{background:linear-gradient(104deg,#DFEEF0,#F6FBFA 66%)}
  .bp2{background:linear-gradient(104deg,#FDFCF8,#F7FAF8 70%)}
  .bp3{background:linear-gradient(104deg,#F6F0E3,#FDFCF7 70%)}
  .bp4{background:linear-gradient(104deg,#E9F3EC,#FBFDFB 70%)}
  .bp5{background:linear-gradient(104deg,#EFF6F6,#FDFCF8 70%)}
  .bp-main{padding:clamp(1.3rem,2.4vw,1.9rem) clamp(1.3rem,2.6vw,2.1rem)}
  .bp-top{display:flex;align-items:center;justify-content:space-between;gap:14px;
    padding-bottom:9px;border-bottom:1px solid rgba(59,131,117,.22);margin-bottom:13px}
  .bp-et{font-family:var(--display);font-weight:800;font-size:.7rem;letter-spacing:.26em;text-transform:uppercase;color:var(--esm)}
  .bp-code{font-family:var(--display);font-weight:700;font-size:.66rem;letter-spacing:.16em;color:rgba(93,124,118,.8)}
  .bp-dl{display:block;font-family:var(--display);font-weight:700;font-size:.6rem;letter-spacing:.22em;
    text-transform:uppercase;color:rgba(93,124,118,.75);margin-bottom:4px}
  .bp h3{font-family:var(--edit);font-weight:600;text-transform:none;letter-spacing:-.02em;
    font-size:clamp(1.55rem,3vw,2.15rem);line-height:1.08;color:var(--tinta);margin-bottom:10px}
  .bp1 h3{font-size:clamp(1.75rem,3.4vw,2.45rem)}
  .bp p{color:var(--tinta2);font-size:clamp(1rem,1.3vw,1.12rem);line-height:1.65;max-width:62ch;margin-bottom:14px}
  .bp-meta{display:flex;justify-content:flex-end;align-items:flex-end}
  .bp-barw{color:var(--tinta);opacity:.42;line-height:0}
  .bp-bar{width:clamp(70px,8vw,96px);height:26px;display:block}
  .bp-stub{position:relative;border-left:1.5px dashed rgba(59,131,117,.45);
    display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:18px 8px}
  .bp-stub::before,.bp-stub::after{content:"";position:absolute;left:-8px;width:15px;height:15px;border-radius:50%;
    background:#FBFCFA;border:1px solid rgba(59,131,117,.24)}
  .bp-stub::before{top:-8px}
  .bp-stub::after{bottom:-8px}
  .bp-w{font-family:var(--display);font-weight:800;font-size:.68rem;letter-spacing:.28em;text-transform:uppercase;
    color:var(--esm);writing-mode:vertical-rl;transform:rotate(180deg)}
  .bp-arw{color:var(--esm);font-size:1.1rem;line-height:1;transition:transform .25s ease}
  .bp:hover .bp-arw{transform:translateX(3px)}
  @media(max-width:680px){
    .bp-stub{flex-direction:row;justify-content:space-between;border-left:0;border-top:1.5px dashed rgba(59,131,117,.45);
      padding:12px 18px;gap:10px}
    .bp-w{writing-mode:horizontal-tb;transform:none}
    .bp-stub::before,.bp-stub::after{left:auto;top:-8px;bottom:auto}
    .bp-stub::before{left:-8px}
    .bp-stub::after{right:-8px}
  }

  /* --- preguntas frecuentes en carrusel --- */
  .fqc-wrap{position:relative}
  .fqc{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;padding:2px 2px 6px}
  .fqc::-webkit-scrollbar{display:none}
  .fqc .fq{flex:0 0 calc((100% - 24px)/3);scroll-snap-align:start;align-self:flex-start}
  @media(max-width:900px){.fqc .fq{flex:0 0 calc((100% - 12px)/2)}}
  @media(max-width:600px){.fqc .fq{flex:0 0 100%}}
  .fqc .fq summary{padding:15px 16px}
  .fqc .fq summary b{font-size:.94rem;line-height:1.3}
  .fqc-ctrl{display:flex;justify-content:center;gap:12px;margin-top:18px}
  .fqc-b{width:40px;height:40px;border-radius:50%;border:1.4px solid rgba(59,131,117,.45);background:transparent;
    color:var(--esm);font-family:var(--sans);font-size:1.3rem;line-height:1;cursor:pointer;display:flex;
    align-items:center;justify-content:center;transition:background .25s ease,color .25s ease,border-color .25s ease}
  .fqc-b:hover{background:var(--esm);color:#fff;border-color:var(--esm)}

scripts:
(function(){
    var c=document.getElementById('fqc');
    if(!c) return;
    document.querySelectorAll('[data-fqc]').forEach(function(b){
      b.addEventListener('click',function(){
        var card=c.querySelector('.fq');
        var paso=card ? card.getBoundingClientRect().width+12 : 300;
        c.scrollBy({left:paso*parseInt(b.dataset.fqc,10),behavior:'smooth'});
      });
    });
  })();
